from fractions import Fraction as Q
from math import factorial, comb
from functools import lru_cache

def moment(p,r,a):
    return Q(0) if r%p else Q(factorial(r),factorial(r//p))*a**(r//p)
def falling(n,r):
    return 0 if n<r else factorial(n)//factorial(n-r)
@lru_cache(None)
def triple(p,d,q,g,a,s,h):
    if q<0 or g<0:return Q(0)
    return sum(comb(g,i)*comb(g-i,j)*moment(p,d+i,a*s)*moment(p,q+j,a*h)*
               moment(p,g-i-j,a*(1-s-h))
               for i in range(g+1) for j in range(g-i+1))

cells=0;critical=0;bounds=0
for m in range(1,5):
    p=2*m
    for T in [Q(1),Q(1,2),Q(5,7)]:
        a=(-1)**(m+1)*T
        for N in [1,2,4,8]:
            h=Q(1,N)
            for j in sorted({0,N//2,N-1}):
                s=j*h
                for d in [0,1,2,3]:
                    for q in sorted({1,p-1,p,p+1,2*p}):
                        for g in [0,1,p-1,p,p+1]:
                            raw=triple(p,d,q,g,a,s,h)
                            product=sum(falling(q-1,k)*p*a*h*comb(p-1,k)*falling(g,p-1-k)*
                                        triple(p,d,q-1-k,g-p+1+k,a,s,h)
                                        for k in range(min(p,q)))
                            assert raw==product
                            if q==p:
                                centered=raw-moment(p,p,a*h)*triple(p,d,0,g,a,s,h)
                                remainder=sum(falling(p-1,k)*p*a*h*comb(p-1,k)*falling(g,p-1-k)*
                                              triple(p,d,p-1-k,g-p+1+k,a,s,h) for k in range(p-1))
                                assert centered==remainder
                                critical+=1
                            cells+=1
            actual=N*(moment(p,2*p,a*h)-moment(p,p,a*h)**2)
            exact=Q(factorial(2*p),2)-factorial(p)**2
            assert actual==exact*a*a/N
            assert actual!=0
            for q in range(p+1,3*p+3):
                C=Q(0) if q%p else Q(factorial(q),factorial(q//p))*T**(q//p)
                assert abs(moment(p,q,a*h))<=C*h*h
                bounds+=1
print(dict(passed=True,exact_signed_cell_tests=cells,critical_cancellations=critical,
           higher_moment_bounds=bounds,finite_mesh_nonzero_diagnostic=True,
           scope='Exact finite signed moments and multinomial expansion; p=2,4,6,8. '
                 'Critical limit is not exact finite-mesh zero; no positivity or full Clark-Ocone inferred.'))
